using System.IO;using System.Diagnostics;using System.Security.Cryptography;using System.Text.Json;using System.Windows;using System.Windows.Media;using System.Windows.Media.Imaging;using RAWSelectionAssistant.Core.Services.Projects;using RAWSelectionAssistant.Core.Services.RawToJpeg;using RAWSelectionAssistant.ViewModels;using RAWSelectionAssistant.Views;using RAWSelectionAssistant.Services;using static RAWSelectionAssistant.WpfTests.RuntimeCorrectionWpfTests;
