[TestClass][DoNotParallelize]public sealed class HomeR55MeasurementsTests
{
 static string Root()=>Environment.GetEnvironmentVariable("KITAO_HOME_R55_ROOT")??throw new InvalidOperationException("Explicit household measurement root required");
 static void Layout(FrameworkElement v){v.Measure(new Size(1366,768));v.Arrange(new Rect(0,0,1366,768));v.UpdateLayout();}
 [TestMethod]public Task HouseholdSameNaturalManifestColdWarmAndCancel()=>RunSta(async()=>{
  EnsureTestApplication();var root=Root();Directory.CreateDirectory(root);var paths=JsonSerializer.Deserialize<string[]>(File.ReadAllText(Environment.GetEnvironmentVariable("KITAO_HOME_R55_MANIFEST")??throw new InvalidOperationException("Explicit source manifest required")))!;Assert.AreEqual(100,paths.Length);var records=new List<object>();
  foreach(int count in new[]{10,100}){
   using var vm=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());var manifest=new List<object>();foreach(var path in paths.Take(count)){using var file=File.OpenRead(path);var hash=Convert.ToHexString(await SHA256.HashDataAsync(file));var bytes=SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(Path.GetFullPath(path)));var id=new Guid(bytes.AsSpan(0,16));var variant=new Guid(bytes.AsSpan(16,16));var target=new ReferenceTargetItem(path,id){SourceHash=hash,IsSelected=true,ActiveEditVersionId=variant};target.EditVersions.Add(new(variant,"家庭授权自然图",DateTimeOffset.UnixEpoch,null,null,hash,null,null,null,ColorStudioMatchEngine.Stable,MatchV4ExecutionMode.Auto){IsOriginal=true,IsMain=true});vm.Targets.Add(target);manifest.Add(new{targetId=id,path,hash});}vm.PinSelectedViewingVariants();new ViewingPreferences(ReduceMotion:true,Sound:false).Save();var notifications=new Dictionary<string,int>();var watch=Stopwatch.StartNew();double? firstVm=null,firstControl=null;bool captureFirst=false;long ws=0,priv=0,managed=0;using var sampling=new CancellationTokenSource();var sampler=Task.Run(async()=>{while(!sampling.IsCancellationRequested){using var process=Process.GetCurrentProcess();ws=Math.Max(ws,process.WorkingSet64);priv=Math.Max(priv,process.PrivateMemorySize64);managed=Math.Max(managed,GC.GetTotalMemory(false));try{await Task.Delay(15,sampling.Token);}catch(OperationCanceledException){}}});var table=new StudioViewingTableView(vm);Layout(table);var initialLayout=watch.Elapsed.TotalMilliseconds;
   vm.PropertyChanged+=(_,args)=>{if(args.PropertyName is{} name)notifications[name]=notifications.GetValueOrDefault(name)+1;if(args.PropertyName==nameof(vm.ViewingFrames)&&vm.ViewingFrames.Count>0){firstVm??=watch.Elapsed.TotalMilliseconds;if(!captureFirst){captureFirst=true;Layout(table);var bitmap=new RenderTargetBitmap(1366,768,96,96,PixelFormats.Pbgra32);bitmap.Render(table);firstControl=watch.Elapsed.TotalMilliseconds;}}};
   await table.RefreshAsync();Layout(table);var complete=watch.Elapsed.TotalMilliseconds;var loaded=vm.ViewingFrames.Count;var failures=vm.ViewingFailures.ToArray();var hashes=vm.ViewingFrames.Select(f=>new{f.Item.VariantId,pixelHash=Hash(f.Image)}).ToArray();var afterCold=new Dictionary<string,int>(notifications);watch.Restart();await table.RefreshAsync();Layout(table);var warm=watch.Elapsed.TotalMilliseconds;watch.Restart();var rendered=new RenderTargetBitmap(1366,768,96,96,PixelFormats.Pbgra32);rendered.Render(table);var render=watch.Elapsed.TotalMilliseconds;var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(rendered));using(var output=File.Create(Path.Combine(root,$"NATURAL-{count}-LOCAL-ONLY.png")))encoder.Save(output);var controls=Walk(table);var realized=table.RealizedCardCount;
   var interactions=new List<object>();foreach(var frame in vm.ViewingFrames.Take(2)){table.SelectForTest(frame);watch.Restart();for(int i=0;i<4;i++)vm.SetViewingPlacement(frame.Item.TargetId,frame.Item.VariantId,frame.Item.X+i,frame.Item.Y+i,1,i*10);Layout(table);interactions.Add(new{frame.Item.VariantId,fourPlacementAndLayoutMs=watch.Elapsed.TotalMilliseconds});}
   var cancelWatch=Stopwatch.StartNew();var pending=table.RefreshAsync();await System.Windows.Threading.Dispatcher.Yield(System.Windows.Threading.DispatcherPriority.Background);vm.CancelViewing();var cancelCommand=cancelWatch.Elapsed.TotalMilliseconds;await pending;var retirement=cancelWatch.Elapsed.TotalMilliseconds;table.Close();sampling.Cancel();await sampler;Assert.AreEqual(0,vm.ViewingCacheBytes);Assert.AreEqual(0,vm.ViewingFrames.Count);
   records.Add(new{count,loaded,failures,initialLayoutMs=initialLayout,firstVmMs=firstVm,firstActualControlRenderMs=firstControl,allCompleteWithControlMs=complete,warmRefreshAndLayoutMs=warm,actualFinalRenderMs=render,realized,controls,peakSampledWorkingSet=ws,peakSampledPrivate=priv,peakSampledManaged=managed,notificationsCold=afterCold,notificationsTotal=notifications,interactions,cancelCommandMs=cancelCommand,cancelRetirementMs=retirement,hashes,manifest,scope="same household 100 natural source list; actual WPF RenderTargetBitmap; no native mouse/DPI"});await File.WriteAllTextAsync(Path.Combine(root,"NATURAL_MEASUREMENTS.json"),JsonSerializer.Serialize(records,new JsonSerializerOptions{WriteIndented=true}));
  }
 });
 [TestMethod]public Task ReproduceOnlySevenPreviousHouseholdFailures()=>RunSta(async()=>{
  EnsureTestApplication();var root=Root();Directory.CreateDirectory(root);using var doc=JsonDocument.Parse(File.ReadAllText(Environment.GetEnvironmentVariable("KITAO_HOME_R55_SEVEN")??throw new InvalidOperationException("Explicit seven sources required")));var rows=new List<object>();foreach(var item in doc.RootElement.EnumerateArray()){var path=item.GetProperty("path").GetString()!;var expected=item.GetProperty("hash").GetString()!;if(!File.Exists(path)){rows.Add(new{path,expected,status="NOT_REPRODUCED_MISSING"});continue;}using(var file=File.OpenRead(path))Assert.AreEqual(expected,Convert.ToHexString(await SHA256.HashDataAsync(file)));var watch=Stopwatch.StartNew();try{var result=await new LibRawDecoder().DecodeViewingProxyAsync(path,640);rows.Add(new{path,sourceSha256=expected,status="DECODED",width=result.Width,height=result.Height,orientation=result.Metadata.Orientation,elapsedMs=watch.Elapsed.TotalMilliseconds,pixelHash=Convert.ToHexString(SHA256.HashData(System.Runtime.InteropServices.MemoryMarshal.AsBytes(result.Rgb48Pixels!.AsSpan())))});}catch(Exception error)when(error is IOException or InvalidOperationException or NotSupportedException or ArgumentException){var native=error as RawDecodeException;var budget=error as StudioBudgetException;rows.Add(new{path,sourceSha256=expected,status="FAILED",type=error.GetType().FullName,message=error.Message,stage=native?.Stage,nativeCode=native?.NativeCode,nativeName=native?.NativeName,required=budget?.RequiredBytes,available=budget?.AvailableBytes,elapsedMs=watch.Elapsed.TotalMilliseconds});}await File.WriteAllTextAsync(Path.Combine(root,"SEVEN_SOURCE_RESULTS.json"),JsonSerializer.Serialize(rows,new JsonSerializerOptions{WriteIndented=true}));}Assert.AreEqual(7,rows.Count);
 });
 [TestMethod]public Task AuthorizedNaturalInteractionSaveAndReopenFixture()=>RunSta(async()=>{
  EnsureTestApplication();var root=Root();Directory.CreateDirectory(root);var paths=JsonSerializer.Deserialize<string[]>(File.ReadAllText(Environment.GetEnvironmentVariable("KITAO_HOME_R55_MANIFEST")!))!;using var vm=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());foreach(var path in paths.Take(2)){var hash=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)));var id=Guid.NewGuid();var variant=Guid.NewGuid();var target=new ReferenceTargetItem(path,id){SourceHash=hash,IsSelected=true,ActiveEditVersionId=variant};target.EditVersions.Add(new(variant,"家庭自然固定快照",DateTimeOffset.UnixEpoch,null,null,hash,null,null,null,ColorStudioMatchEngine.Stable,MatchV4ExecutionMode.Auto){IsOriginal=true});vm.Targets.Add(target);}vm.PinSelectedViewingVariants();new ViewingPreferences(ReduceMotion:true,Sound:false).Save();var table=new StudioViewingTableView(vm);Layout(table);await table.RefreshAsync();Assert.AreEqual(2,vm.ViewingFrames.Count);var first=vm.ViewingTable.Items[0];var recipe=first.RecipeHash;table.SelectForTest(vm.ViewingFrames[0]);vm.BeginViewingGesture();vm.SetViewingPlacement(first.TargetId,first.VariantId,300,210,1.3,90);vm.CommitViewingGesture();Layout(table);var source=vm.ViewingFrames[0].Image;var matrix=table.SelectedPixelMatrixForTest(source);var known=new Point(source.PixelWidth*.4,source.PixelHeight*.6);Assert.IsTrue(table.MapLoupeForTest(matrix.Transform(known),source,out var actual));Assert.AreEqual(known.X,actual.X,1e-7);Assert.AreEqual(recipe,vm.ViewingTable.Items.First(i=>i.VariantId==first.VariantId).RecipeHash);await table.LoupeForHost();table.HandleShortcut(System.Windows.Input.Key.A,System.Windows.Input.ModifierKeys.None);table.SelectVariantsForTest(vm.ViewingFrames.Select(f=>f.Item.VariantId).ToArray());await table.CompareAsync();Assert.AreEqual(2,table.LastComparisonVariants.Count);table.ExitDetailForHost();table.DetailRenderer=(item,edge,t)=>Task.FromResult(vm.ViewingFrames.First(f=>f.Item.VariantId==item.VariantId).Image);await table.StartSlideshowForTest();table.PauseSlideshowForTest();Assert.IsTrue(table.SlideshowPaused);table.ExitDetailForHost();vm.UndoViewing();Assert.AreEqual(0d,vm.ViewingTable.Items.First(i=>i.VariantId==first.VariantId).Rotation);vm.RedoViewing();var file=Path.Combine(root,"natural-local-only.ptstudio.json");await vm.SaveSessionAsync(file);var expected=JsonSerializer.Serialize(vm.ViewingTable);await File.WriteAllTextAsync(Path.Combine(root,"NATURAL_REOPEN_EXPECTED.json"),JsonSerializer.Serialize(new{pid=Environment.ProcessId,file,expected}));table.Close();using var other=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());await other.LoadSessionAsync(file);Assert.AreEqual(expected,JsonSerializer.Serialize(other.ViewingTable));new ViewingPreferences().Save();
 });
 [TestMethod]public Task IndependentNaturalProjectReopen()=>RunSta(async()=>{EnsureTestApplication();using var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(Root(),"NATURAL_REOPEN_EXPECTED.json")));Assert.AreNotEqual(Environment.ProcessId,doc.RootElement.GetProperty("pid").GetInt32());using var vm=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());await vm.LoadSessionAsync(doc.RootElement.GetProperty("file").GetString()!);Assert.AreEqual(doc.RootElement.GetProperty("expected").GetString(),JsonSerializer.Serialize(vm.ViewingTable));await vm.PrepareViewingTableAsync();Assert.AreEqual(2,vm.ViewingFrames.Count);vm.ReleaseViewing();});
 [TestMethod]public Task ExactAuthorizedFujiRepeatabilityNoDecoderChanges()=>RunSta(async()=>{EnsureTestApplication();var root=Root();Directory.CreateDirectory(root);var manifest=JsonSerializer.Deserialize<string[]>(File.ReadAllText(Environment.GetEnvironmentVariable("KITAO_HOME_R55_MANIFEST")!))!;var rows=new List<object>();foreach(var name in new[]{"DSCF0347.RAF","DSCF0370.RAF"}){var path=manifest.Single(p=>Path.GetFileName(p)==name);var images=new List<ushort[]>();for(int n=0;n<3;n++){var decoded=await new LibRawDecoder().DecodeViewingProxyAsync(path,ViewingProxyEdge());images.Add(decoded.Rgb48Pixels!);}var differences=images[0].Zip(images[1],(a,b)=>Math.Abs(a-b)).ToArray();var other=images[1].Zip(images[2],(a,b)=>Math.Abs(a-b)).ToArray();rows.Add(new{name,sourceHash=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))),hashes=images.Select(p=>Convert.ToHexString(SHA256.HashData(System.Runtime.InteropServices.MemoryMarshal.AsBytes(p.AsSpan())))).ToArray(),firstPair=new{different=differences.Count(n=>n!=0),max16=differences.Max(),mean16=differences.Average()},secondPair=new{different=other.Count(n=>n!=0),max16=other.Max(),mean16=other.Average()},scope="same native product decoder repeated 3 times; unchanged mathematical settings; no UI or cache transform"});}await File.WriteAllTextAsync(Path.Combine(root,"FUJI_REPEATABILITY.json"),JsonSerializer.Serialize(rows,new JsonSerializerOptions{WriteIndented=true}));static int ViewingProxyEdge()=>Math.Min(640,Math.Max(128,(int)Math.Sqrt(32d*1024*1024/100/4)));});
 [TestMethod]public Task ExplicitNaturalHundredCacheAccounting()=>RunSta(async()=>{EnsureTestApplication();var root=Root();Directory.CreateDirectory(root);var paths=JsonSerializer.Deserialize<string[]>(File.ReadAllText(Environment.GetEnvironmentVariable("KITAO_HOME_R55_MANIFEST")!))!;using var vm=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());foreach(var path in paths){var h=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)));var id=Guid.NewGuid();var target=new ReferenceTargetItem(path){SourceHash=h,IsSelected=true,ActiveEditVersionId=id};target.EditVersions.Add(new(id,"自然缓存核验",DateTimeOffset.UnixEpoch,null,null,h,null,null,null,ColorStudioMatchEngine.Stable,MatchV4ExecutionMode.Auto){IsOriginal=true});vm.Targets.Add(target);}vm.PinSelectedViewingVariants();await vm.PrepareViewingTableAsync();var cold=new{loaded=vm.ViewingFrames.Count,failed=vm.ViewingFailures.Count,bytes=vm.ViewingCacheBytes,hashReads=vm.ViewingHashReads,decodeCount=vm.ViewingDecodeCount,active=vm.ViewingActiveRenders,peakActive=vm.ViewingPeakActiveRenders};await vm.PrepareViewingTableAsync();var warm=new{loaded=vm.ViewingFrames.Count,failed=vm.ViewingFailures.Count,bytes=vm.ViewingCacheBytes,hashReads=vm.ViewingHashReads,decodeCount=vm.ViewingDecodeCount,active=vm.ViewingActiveRenders,peakActive=vm.ViewingPeakActiveRenders};Assert.AreEqual(94,warm.loaded);Assert.AreEqual(6,warm.failed);Assert.IsTrue(warm.bytes<=64L*1024*1024);Assert.AreEqual(cold.decodeCount+6,warm.decodeCount,"Only unsupported files are retried, successful sources stay cached");vm.ReleaseViewing();Assert.AreEqual(0L,vm.ViewingCacheBytes);await File.WriteAllTextAsync(Path.Combine(root,"NATURAL_CACHE_ACCOUNTING.json"),JsonSerializer.Serialize(new{cold,warm,releasedBytes=vm.ViewingCacheBytes,scope="separate sequential cache accounting; not additional timed P95 sample"},new JsonSerializerOptions{WriteIndented=true}));});
 static int Walk(DependencyObject d){int count=1;for(int i=0;i<VisualTreeHelper.GetChildrenCount(d);i++)count+=Walk(VisualTreeHelper.GetChild(d,i));return count;}
 static string Hash(BitmapSource b){var f=new FormatConvertedBitmap(b,PixelFormats.Bgra32,null,0);var a=new byte[f.PixelWidth*f.PixelHeight*4];f.CopyPixels(a,f.PixelWidth*4,0);return Convert.ToHexString(SHA256.HashData(a));}
